<?php
namespace App\Http\Controllers;
use App\Http\Requests\JobRequest; use App\Models\{Job,JobCategory}; use App\Repositories\Contracts\JobRepositoryInterface; use App\Services\JobService; use Illuminate\Http\{RedirectResponse,Request}; use Illuminate\View\View;
class JobController extends Controller { public function __construct(private JobRepositoryInterface $jobs,private JobService $service){} public function index(Request $request):View{return view('jobs.index',['jobs'=>$this->jobs->paginatePublished($request->only(['search','category','location'])),'categories'=>JobCategory::orderBy('name')->get()]);} public function show(Job $job):View{$job->load(['company.user','category','requirements'])->loadCount('applications');return view('jobs.show',compact('job'));} public function manage(Request $request):View{$query=Job::with('category')->withCount('applications');if(!$request->user()->hasRole('admin'))$query->where('company_id',$request->user()->company->id);return view('jobs.manage',['jobs'=>$query->latest()->paginate(10),'categories'=>JobCategory::orderBy('name')->get()]);} public function store(JobRequest $request):RedirectResponse{$this->service->create($request->user()->company,$request->validated());return back()->with('success','Lowongan berhasil dibuat.');} public function update(JobRequest $request,Job $job):RedirectResponse{abort_unless($request->user()->hasRole('admin')||$job->company_id===$request->user()->company?->id,403);$this->service->update($job,$request->validated());return back()->with('success','Lowongan diperbarui.');} public function destroy(Request $request,Job $job):RedirectResponse{abort_unless($request->user()->hasRole('admin')||$job->company_id===$request->user()->company?->id,403);$this->service->delete($job);return back()->with('success','Lowongan dihapus.');} }
